def check_order(core, order_links, scopes):
    """Validate the elimination order and the promised width."""
    if len(order_links) != len(core):
        raise Invalid('order length')
    seen = set()
    for link in order_links:
        if link in seen:
            raise Invalid('duplicate order entry')
        seen.add(link)
    if seen != set(core):
        raise Invalid('order is not a permutation of the core links')
    index = {link: position for position, link in enumerate(core)}
    adjacency = {position: set() for position in range(len(core))}
    for scope in scopes.values():
        for a in scope:
            for b in scope:
                if a != b:
                    adjacency[a].add(b)
    for link in order_links:
        node = index[link]
        neighbours = adjacency[node]
        if len(neighbours) > MAX_WIDTH:
            raise Invalid('width promise violated')
        group = list(neighbours)
        for a in group:
            for b in group:
                if a != b:
                    adjacency[a].add(b)
                    adjacency[b].add(a)
        for a in group:
            adjacency[a].discard(node)
        del adjacency[node]
    return [index[link] for link in order_links]


def expand_to(src_vars, src_table, dst_vars):
    """Broadcast a factor table onto the variable set dst_vars."""
    position = {var: i for i, var in enumerate(src_vars)}
    source = [0]
    for var in dst_vars:
        slot = position.get(var)
        if slot is None:
            grown = []
            for value in source:
                grown.append(value)
                grown.append(value)
                grown.append(value)
        else:
            stride = 3 ** (len(src_vars) - 1 - slot)
            grown = []
            for value in source:
                base = value - (value // stride % 3) * stride
                grown.append(base)
                grown.append(base + stride)
                grown.append(base + 2 * stride)
        source = grown
    return [src_table[value] for value in source]


def multiply(first, second):
    """Product of two factors over the union of their variables."""
    vars_a, table_a = first
    vars_b, table_b = second
    if vars_a == vars_b:
        return (vars_a, [x * y for x, y in zip(table_a, table_b)])
    union = tuple(sorted(set(vars_a) | set(vars_b)))
    wide = expand_to(vars_a, table_a, union)
    narrow = expand_to(vars_b, table_b, union)
    return (union, [x * y for x, y in zip(wide, narrow)])


def sum_out(factor, variable):
    """Marginalise one variable out of a factor."""
    variables, table = factor
    size = len(variables)
    slot = variables.index(variable)
    stride = 3 ** (size - 1 - slot)
    powers = [1] * (size + 1)
    for i in range(size):
        powers[i + 1] = powers[i] * 3
    result = [0] * powers[size - 1]
    for old in range(powers[size]):
        digit = (old // stride) % 3
        base = old - digit * stride
        new = (base // (3 * stride)) * stride + (base % stride)
        result[new] += table[old]
    keep = variables[:slot] + variables[slot + 1:]
    return (keep, result)


def eliminate(factors, order, skip=None):
    """Bucket elimination; returns the factors left in the pool."""
    pool = list(factors)
    for variable in order:
        if variable == skip:
            continue
        bucket = []
        rest = []
        for factor in pool:
            if variable in factor[0]:
                bucket.append(factor)
            else:
